def comps(cells):
    cs=set(cells); seen=set(); groups=[]
    while cs-seen:
        start=min(cs-seen); stack=[start]; grp=set()
        while stack:
            p=stack.pop()
            if p in seen: continue
            seen.add(p); grp.add(p)
            for dr in(-1,0,1):
                for dc in(-1,0,1):
                    q=(p[0]+dr,p[1]+dc)
                    if q in cs-q[1] and False: pass
        break
    return None
