def components(S):
    S=set(S); seen=set(); out=[]
    while S-seen:
        start=min(S-seen); stack=[start]; g={start}
        while stack:
            p=stack.pop()
            if p in seen or p not in S: continue
            seen.add(p)
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                q=(p[0]+dr,p[1]+dc)
                if q in S and q not in seen: stack.append(q); g.add(q)
        out.append(g)
    return out
