def comps(g,exclude=()):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; res=[]
    for r in range(H):
        for c in range(W):
            if g[r][c] not in exclude and not seen[r][c]:
                st=[(r,c)]; col=g[r][c]; cells=set()
                while st:
                    a,b=st.pop()
                    if (a,b) in cells or seen[a][b]: continue
                    cells.add((a,b)); seen[a][b]=True
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
